package ro.leo.visual;
import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;
public final class LyricsActivity extends LeoActivity {
 private LyricsData.Document document=new LyricsData.Document();private String source=null,title="Versuri locale",status="";private int selected,request;private boolean follow=true,visible,lyricsScreen;private Face face;private final Handler handler=new Handler();
 private String current(){PlaybackService s=PlaybackService.instance;return s==null||s.queue.index<0?"":s.queue.sources.get(s.queue.index);}
 private final Runnable tick=new Runnable(){public void run(){if(!visible)return;String next=current();if(!next.equals(source)){source=next;read(LyricsData.sidecar(LyricsActivity.this,next));}PlaybackService s=PlaybackService.instance;if(follow&&document.timed)selected=Math.max(0,document.active(s==null?0:s.position()));if(face!=null)face.invalidate();handler.postDelayed(this,s!=null&&s.playing()?250:1000);}};
 protected void onCreate(Bundle b){super.onCreate(b);screen();}
 protected void onResume(){super.onResume();visible=true;handler.post(tick);}protected void onPause(){visible=false;handler.removeCallbacks(tick);super.onPause();}
 protected void onDestroy(){request++;super.onDestroy();}
 private void screen(){lyricsScreen=true;begin("Versuri Leo");face=new Face();root.addView(face,new LinearLayout.LayoutParams(-1,0,1));left=new Runnable(){public void run(){options("Versuri locale",new String[]{"Alege fișier LRC",follow?"Derulare manuală":"Urmărește muzica","Reîncarcă LRC automat","Cum adaug versuri?"},new Choice(){public void pick(int n){if(n==0)browse();else if(n==1){follow=!follow;screen();}else if(n==2){source=current();read(LyricsData.sidecar(LyricsActivity.this,source));}else startActivity(new Intent(LyricsActivity.this,HelpActivity.class).putExtra("topic",4));}});}};back=null;footer("Opțiuni",follow?"OK: manual":"OK: auto","Înapoi");face.setFocusable(true);face.requestFocus();}
 private void read(final File f){final int token=++request;document=new LyricsData.Document();selected=0;status=f==null?"Pune un .lrc lângă piesă sau alege din Opțiuni":"Se citesc versurile…";title=f==null?"Versuri locale":f.getName();if(face!=null)face.invalidate();if(f==null)return;worker.execute(new Runnable(){public void run(){LyricsData.Document loaded=null;String error="";try{loaded=LyricsData.read(LyricsActivity.this,f);}catch(Exception e){error="LRC indisponibil sau peste limită";}final LyricsData.Document data=loaded;final String message=error;ui(new Runnable(){public void run(){if(token!=request)return;document=data==null?new LyricsData.Document():data;status=data==null?message:data.lines.isEmpty()?"Fișier fără versuri":"";follow=document.timed;selected=0;if(lyricsScreen)screen();}});}});}
 private void browse(){final String track=current();worker.execute(new Runnable(){public void run(){final ArrayList<File> files=LyricsData.files(LyricsActivity.this,track);ui(new Runnable(){public void run(){ArrayList<String> labels=new ArrayList<String>();for(File f:files)labels.add(f.getName());lyricsScreen=false;list("Fișiere LRC locale",labels,0,new Choice(){public void pick(int n){read(files.get(n));screen();}},"Player",new Runnable(){public void run(){screen();}});back=new Runnable(){public void run(){screen();}};}});}});}
 public boolean onKeyDown(int key,KeyEvent e){if(lyricsScreen&&face!=null){if(key==KeyEvent.KEYCODE_DPAD_UP||key==KeyEvent.KEYCODE_DPAD_DOWN){follow=false;selected=CircularNavigation.step(selected,key==KeyEvent.KEYCODE_DPAD_DOWN?1:-1,document.lines.size());face.invalidate();return true;}if(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER){if(e.getRepeatCount()==0){follow=!follow;screen();}return true;}}return super.onKeyDown(key,e);}
 private final class Face extends View{final Paint p=new Paint(3);Face(){super(LyricsActivity.this);}void label(Canvas c,String s,int x,int y,int size,int color){p.setTextSize(size);p.setColor(color);p.setTextAlign(Paint.Align.CENTER);if(p.measureText(s)>216){int count=p.breakText(s,true,216-p.measureText("…"),null);s=s.substring(0,count)+"…";}c.drawText(s,x,y,p);}protected void onDraw(Canvas c){c.save();c.scale(getWidth()/240f,getHeight()/224f);c.drawColor(palette.background);label(c,title,120,23,13,palette.accent);if(document.lines.isEmpty()){label(c,"Niciun vers încărcat",120,95,18,Color.WHITE);label(c,status,120,129,12,palette.accent);}else{int first=Math.max(0,Math.min(Math.max(0,document.lines.size()-5),selected-2));for(int row=0;row<5&&first+row<document.lines.size();row++){int at=first+row,y=47+row*31;if(at==selected){p.setColor(palette.card);c.drawRoundRect(6,y-19,234,y+9,5,5,p);}label(c,document.lines.get(at).text,120,y,at==selected?16:13,at==selected?palette.accent:0xffbecad1);}label(c,(document.timed?"LRC sincronizat":"Text local")+" · "+(follow?"auto":"manual"),120,214,11,palette.accent);}c.restore();}}
}
